insert into bestkebab.site_content (id, data) values (1, $bk${"version": 1, "business": {"name": "Best Kebab", "since": "2012", "tagline": "Kebab, frites & crêpes — Tlemcen et sa région", "instagram": [{"handle": "@best_kebab_tlemcan", "url": "https://www.instagram.com/best_kebab_tlemcan/"}, {"handle": "@bestkebab.tlemcen", "url": "https://www.instagram.com/bestkebab.tlemcen/"}], "main_branch": "tlemcen"}, "hero": {"kicker": "Depuis 2012 · Tlemcen · Maghnia · Remchi · Port-Say", "title": "Le kebab qui *tourne* depuis 2012.", "tagline": "Matloua, libanais, panini ou plat kebab : composez votre commande en quelques touches, puis passez la prendre ou faites-vous livrer."}, "ordering": {"open": true, "delivery": true, "closed_text": "La commande en ligne est momentanément fermée. Appelez la boutique pour commander.", "delivery_note": "Livraison : zone, délai et éventuels frais à confirmer par la boutique au téléphone.", "pickup_note": "La boutique vous appelle pour confirmer avant de lancer la préparation."}, "hours": {"text": "Horaires à confirmer, appelez-nous.", "note": "Best Kebab Remchi : ouverture à 18h00 indiquée sur Yassir."}, "branches": [{"key": "tlemcen", "name": "Best Kebab Tlemcen", "city": "Tlemcen", "address": "Kiffane — à côté de Best Chicken, Résidence Mittak, Bd Sbiaa Ali, El Kiffane 13000 (adresse à confirmer)", "phone": "0559 85 80 31", "phone_intl": "+213559858031", "maps_url": "https://www.google.com/maps/search/?api=1&query=Best+Kebab+Kiffane+Tlemcen", "hours": "Horaires à confirmer, appelez-nous", "orders": true, "main": true}, {"key": "maghnia", "name": "Best Kebab Maghnia", "city": "Maghnia", "address": "Maghnia (adresse à confirmer)", "phone": "0541 82 10 84", "phone_intl": "+213541821084", "maps_url": "https://www.google.com/maps/search/?api=1&query=Best+Kebab+Maghnia", "hours": "Horaires à confirmer, appelez-nous", "orders": true}, {"key": "remchi", "name": "Best Kebab Remchi", "city": "Remchi", "address": "Remchi (3H58+5GW)", "phone": "0696 29 44 66", "phone_intl": "+213696294466", "maps_url": "https://www.google.com/maps/place/Best+kebab/@35.058228,-1.4337036,17z", "hours": "Ouverture 18h00 (selon Yassir) — à confirmer", "orders": true}, {"key": "portsay", "name": "Best Kebab Port-Say", "city": "Port-Say (Marsa Ben M'hidi)", "address": "Port-Say / Marsa Ben M'hidi (adresse à confirmer)", "phone": "0557 11 38 63", "phone_intl": "+213557113863", "maps_url": "https://www.google.com/maps/search/?api=1&query=Best+Kebab+Marsa+Ben+M%27hidi", "hours": "Horaires à confirmer, appelez-nous", "orders": true}], "menu": {"currency": "DA", "note": "Prix relevés sur la carte Yassir de Best Kebab Remchi (cornet de frites : panneau en boutique). Ils peuvent varier selon la boutique : la boutique confirme le total au téléphone.", "categories": [{"key": "sandwichs", "title": "Sandwichs kebab", "desc": "Viande grillée à la broche verticale, tranchée minute.", "items": [{"id": "matloua", "name": "Matloua Kebab", "desc": "Kebab dans une galette matloua.", "price": "450", "photo": "matloua", "available": true, "tag": "Le classique"}, {"id": "libanais", "name": "Libanais Kebab", "desc": "Kebab roulé dans un pain libanais.", "price": "450", "photo": "libanais", "available": true}, {"id": "panini", "name": "Panini Kebab", "desc": "Kebab dans un panini pressé.", "price": "450", "photo": "panini", "available": true}]}, {"key": "plats", "title": "Plats", "desc": "À l’assiette, pour les grosses faims.", "items": [{"id": "plat-kebab", "name": "Plat Kebab", "desc": "Kebab servi à l’assiette.", "price": "800", "photo": "plat", "available": true, "tag": "Copieux"}, {"id": "plat-frite", "name": "Plat Frite", "desc": "Assiette de frites.", "price": "300", "photo": "frites", "available": true}]}, {"key": "frites", "title": "Frites", "desc": "Dorées et croustillantes.", "items": [{"id": "barquette-frite", "name": "Barquette de Frite", "desc": "", "price": "200", "photo": "frites", "available": true}, {"id": "cornet-frite", "name": "Cornet de frite", "desc": "Prix affiché sur le panneau en boutique.", "price": "80", "photo": "frites", "available": true}]}, {"key": "crepes", "title": "Crêpes", "desc": "Les crêpes de la maison — très appréciées des clients.", "items": [{"id": "crepes", "name": "Crêpes", "desc": "Garnitures et prix à venir : demandez en boutique.", "price": "", "photo": "crepe", "available": true}]}]}, "reviews": {"source": "Avis Google Maps — Best Kebab Remchi (4,2★, 12 avis, relevé le 16/10/2026)", "items": [{"author": "FethAllah Chabouni", "when": "il y a environ 3 mois", "text": "Restaurant très propre et coloré… accueil au top, service rapide, sandwich bien garni"}, {"author": "Med Amine Mohammedi", "when": "il y a environ 3 mois", "text": "Meilleur Kebab à Tlemcen depuis son ouverture… qualité goût accueil et hygiène"}, {"author": "Nadoushka", "when": "il y a environ 6 mois", "text": "Excellentes crêpes et très bon service !"}]}, "about": {"title": "Quatre boutiques, *une seule broche* : la nôtre.", "text": "Best Kebab sert Tlemcen et sa région depuis 2012, avec des boutiques à Tlemcen (Kiffane), Maghnia, Remchi et Port-Say.", "quote": "The best things in life (kebab) are meant to be shared"}, "photos": {"hero": {"label": "Grande photo d’accueil", "src": "", "alt": "Kebab tranché à la broche verticale (illustration)"}, "spit": {"label": "Broche (section maison)", "src": "", "alt": "Broches de kebab verticales (illustration)"}, "matloua": {"label": "Matloua Kebab", "src": "", "alt": "Sandwich kebab garni (illustration)"}, "libanais": {"label": "Libanais Kebab", "src": "", "alt": "Wraps kebab roulés (illustration)"}, "panini": {"label": "Panini Kebab", "src": "", "alt": "Panini pressé coupé en deux (illustration)"}, "plat": {"label": "Plat Kebab", "src": "", "alt": "Kebab et frites (illustration)"}, "frites": {"label": "Frites", "src": "", "alt": "Frites dorées en barquette (illustration)"}, "crepe": {"label": "Crêpes", "src": "", "alt": "Crêpe aux fraises en cornet (illustration)"}, "wall": {"label": "Mur de la boutique de Remchi (photo réelle)", "src": "", "alt": "Mur de Best Kebab Remchi : « The best things in life (kebab) are meant to be shared »"}, "store": {"label": "Devanture (photo réelle)", "src": "", "alt": "Devanture d’une boutique Best Kebab avec l’enseigne rouge"}}}$bk$::jsonb) on conflict (id) do nothing;
